package ru.billyhargrove.pimobile.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class WorkTimelineTest {
 private ChatMessage m(String id,ChatMessage.Role role,String phase){return ChatMessage.remote(id,role,id,null,role==ChatMessage.Role.TOOL_RESULT?"bash":null).withPresentation("turn1",phase,"{}","");}
 @Test public void toolsAndCommentaryShareOneBlockButFinalAnswerStaysOutside(){List<ChatMessage> ms=Arrays.asList(m("u",ChatMessage.Role.USER,"answer"),m("a",ChatMessage.Role.ASSISTANT,"work"),m("t1",ChatMessage.Role.TOOL_RESULT,"work"),m("b",ChatMessage.Role.ASSISTANT,"work"),m("t2",ChatMessage.Role.TOOL_RESULT,"work"),m("final",ChatMessage.Role.ASSISTANT,"answer"));List<WorkTimeline.Row> rows=WorkTimeline.build(ms,Collections.emptySet());assertEquals(7,rows.size());assertEquals(1,rows.stream().filter(r->r.header).count());assertEquals("b",rows.get(4).message.id());assertFalse(rows.get(6).work());List<WorkTimeline.Row> closed=WorkTimeline.build(ms,Collections.singleton("turn1"));assertEquals(3,closed.size());assertEquals("final",closed.get(2).message.id());}
 @Test public void prependPreservesCanonicalLiveUpdates(){TranscriptStore s=new TranscriptStore();s.replaceAll(Arrays.asList(m("b",ChatMessage.Role.ASSISTANT,"answer")));s.prepend(Arrays.asList(m("a",ChatMessage.Role.USER,"answer"),m("b",ChatMessage.Role.ASSISTANT,"work")));assertEquals(2,s.size());assertEquals("a",s.transcript().get(0).id());assertEquals("answer",s.transcript().get(1).phase());assertTrue(s.hasUniqueIds());}
 @Test public void mathPreservesCodeAndCurrency(){assertEquals("$$x^2$$",MathMarkdown.normalize("$x^2$"));assertEquals("`$x$`",MathMarkdown.normalize("`$x$`"));assertEquals("```\n$x$\n```",MathMarkdown.normalize("```\n$x$\n```"));assertEquals("$5 and $10",MathMarkdown.normalize("$5 and $10"));assertTrue(MathMarkdown.normalize("\\[x^2\\]").contains("$$\nx^2\n$$"));}
}
